    if n == 0:
        return 0
    dp = [0] * (n + 1)
    for i in range(1, n + 1):
        if i == 1:
            dp[i] = cost[0]
        elif i == 2:
            dp[i] = min(cost[0], cost[1])
        else:
            dp[i] = cost[i - 1] + min(dp[i - 1], dp[i - 2])
    return dp[n]
```

