```python
def centroid(points):
    if not points:
        return None
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    return (sum(xs) / len(xs), sum(ys) / len(ys))
```

```python
def unique_tags(text):
    seen = set()
    out = []
    for token in text.split():
        if token.startswith('#'):
            tag = token[1:].lower()
            if tag not in seen:
                seen.add(tag)
                out.append(tag)
    return out
```

```python
def vowel_percentage(s):
    if not s:
        return 0
    vowels = sum(1 for c in s.lower() if c in 'aeiou')
    return round(vowels * 100 // len(s))
```

