```python
def count_safe_orderings(balance, transactions):
    from itertools import permutations
    count = 0
    for order in set(permutations(transactions)):
        total = balance
        ok = True
        for t in order:
            total += t
            if total < 0:
                ok = False
                break
        if ok:
            count += 1
    return count
```

