    if not letters:
        return 0.0
    return round(sum(points[c] for c in letters) / len(letters), 2)
```

```python
def min_position(matrix):
    if not matrix or not matrix[0]:
        return None
    best = (0, 0)
    for i, row in enumerate(matrix):
        for j, count in enumerate(row):
            if count < matrix[best[0]][best[1]]:
                best = (i, j)
    return best
```

