```python
def occurrence_matrix(matrix):
    counts = {}
    for row in matrix:
        for cell in row:
            counts[cell] = counts.get(cell, 0) + 1
    return [[counts[cell] for cell in row] for row in matrix]
```

```python
def reverse_numbers_in_text(text):
    import re
    def rev(n):
        return int(str(abs(n))[::-1]) * (1 if n >= 0 else -1)
    return re.sub(r'-?\d+', lambda m: str(rev(int(m.group()))), text)
```

```python
def total_improvement(grades):
    total = 0
    for i in range(1, len(grades)):
        if grades[i] > grades[i - 1]:
            total += grades[i] - grades[i - 1]
    return total
```

```python
def longest_zigzag(grades):
    if not grades:
        return 0
    up = down = 1
    for i in range(1, len(grades)):
        if grades[i] > grades[i - 1]:
            up = down + 1
        elif grades[i] < grades[i - 1]:
            down = up + 1
    return max(up, down)
```

```python
def longest_overdraft_run(s):
    best = 0
    cur = 0
    for ch in s:
        if ch == '-':
            cur += 1
            if cur > best:
                best = cur
        else:
            cur = 0
    return best
```

```python
def eval_postfix_digits(expr):
    ops = {'+': lambda a, b: a + b, '-': lambda a, b: a - b, '*': lambda a, b: a * b, '/': lambda a, b: a // b}
    stack = []
    for ch in expr:
        if ch in ops:
            b, a = stack.pop(), stack.pop()
            stack.append(ops[ch](a, b))
        else:
            stack.append(int(ch))
    return stack[0]
```

```python
def extreme_positions(measurements):
    if not measurements:
        return None
    lo = min(measurements)
    hi = max(measurements)
    return (measurements.index(lo), measurements.index(hi))
```

```python
def has_gap_pair(times, k):
    lo, hi = 0, len(times) - 1
    while lo < hi:
        diff = times[hi] - times[lo]
        if diff == k:
            return True
        if diff < k:
            lo += 1
        else:
            hi -= 1
    return False
```

