```python
def collapse_repeats(text):
    import re
    return re.sub(r'\b(\w+)(?:\s+\1\b)+', r'\1', text, flags=re.IGNORECASE)
```

```python
def remove_duplicate_digits(n):
    seen = set()
    result = []
    for ch in str(n):
        if ch not in seen:
            seen.add(ch)
            result.append(ch)
    return int(''.join(result))
```

